1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_MULTIPLIER = 1.10;
11	const FLOAT_TOLERANCE = 1e-9;
12	
13	const BASE_PREMIUM: Record<string, number> = {
14	  sword: 100,
15	  amulet: 60,
16	  staff: 80,
17	  potion: 40,
18	  rune: 25,
19	  moonstone: 25,
20	};
21	
22	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
23	
24	const basePremiumOf = (item: Item): number => BASE_PREMIUM[item.type];
25	
26	const sumBasePremiums = (items: Item[]): number =>
27	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
28	
29	const computeQuotePremium = (items: Item[]): number =>
30	  roundUp(sumBasePremiums(items) * FIRST_INSURANCE_MULTIPLIER + PROCESSING_FEE);
31	
32	export const runScenario = (scenario: Scenario): ScenarioResult => ({
33	  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items) })),
34	});
